import * as monaco from 'monaco-editor';

interface EditorProps {
  language: string;
  value: string;
  onChange: (value: string) => void;
}

export const CodeEditor: React.FC<EditorProps> = ({
  language,
  value,
  onChange
}) => {
  const editorRef = useRef<monaco.editor.IStandaloneCodeEditor>();

  useEffect(() => {
    const editor = monaco.editor.create(containerRef.current, {
      value,
      language,
      theme: 'vs-dark',
      automaticLayout: true,
      minimap: { enabled: false },
      fontSize: 14,
      lineNumbers: 'on',
      roundedSelection: false,
      scrollBeyondLastLine: false,
      readOnly: false
    });

    editor.onDidChangeModelContent(() => {
      onChange(editor.getValue());
    });

    editorRef.current = editor;

    return () => editor.dispose();
  }, [language]);

  return <div ref={containerRef} style={{ height: '100%' }} />;
};

interface TransformationState {
  status: 'idle' | 'analyzing' | 'transforming' | 'complete' | 'error';
  progress: number;
  result?: TransformResult;
  error?: Error;
}

export const TransformationDashboard: React.FC = () => {
  const [state, setState] = useState<TransformationState>({
    status: 'idle',
    progress: 0
  });

  const handleTransform = async (request: TransformRequest) => {
    setState({ status: 'analyzing', progress: 0 });

    try {
      const response = await fetch('/api/transform', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(request)
      });

      const reader = response.body?.getReader();
      const decoder = new TextDecoder();

      while (true) {
        const { done, value } = await reader!.read();
        if (done) break;

        const chunk = decoder.decode(value);
        const progress = JSON.parse(chunk);

        setState(prev => ({
          ...prev,
          status: progress.status,
          progress: progress.percentage
        }));
      }

      setState(prev => ({
        ...prev,
        status: 'complete',
        result: await response.json()
      }));
    } catch (error) {
      setState({ status: 'error', progress: 0, error });
    }
  };

  return (
    <div className="dashboard">
      <TransformationProgress state={state} />
      <ResultsViewer result={state.result} />
    </div>
  );
};

