import { Redis } from 'ioredis';

class TransformationCache {
  private redis: Redis;
  private ttl = 3600;

  constructor() {
    this.redis = new Redis({
      host: process.env.REDIS_HOST,
      port: parseInt(process.env.REDIS_PORT || '6379'),
      password: process.env.REDIS_PASSWORD
    });
  }

  async get(key: string): Promise<TransformResult | null> {
    const cached = await this.redis.get(key);
    return cached ? JSON.parse(cached) : null;
  }

  async set(key: string, value: TransformResult): Promise<void> {
    await this.redis.setex(
      key,
      this.ttl,
      JSON.stringify(value)
    );
  }

  generateKey(request: TransformRequest): string {
    const normalized = {
      source: request.sourceCode.trim(),
      sourceLang: request.sourceLanguage,
      targetLang: request.targetLanguage,
      options: request.options || {}
    };
    return crypto
      .createHash('sha256')
      .update(JSON.stringify(normalized))
      .digest('hex');
  }
}
